package order

import (
  "database/sql"
  "testing"

  "github.com/stretchr/testify/suite"
)

type ServiceSuite struct {
  suite.Suite
  db  *sql.DB
  svc *Service
}

func (s *ServiceSuite) SetupTest() {
  s.db = openTestDB(s.T())
  s.svc = NewService(NewRepo(s.db), fixedClock{})
}

func (s *ServiceSuite) TearDownTest() {
  s.db.Close()
}

func (s *ServiceSuite) TestCreate() {
  id, err := s.svc.Create("alice", 3)
  s.Require().NoError(err)
  s.NotZero(id)
}

func (s *ServiceSuite) TestCancel() {
  id, err := s.svc.Create("alice", 3)
  s.Require().NoError(err)
  s.NoError(s.svc.Cancel(id))
}

func (s *ServiceSuite) TestCreateRejectsZero() {
  _, err := s.svc.Create("alice", 0)
  s.Error(err)
}

func TestServiceSuite(t *testing.T) {
  suite.Run(t, new(ServiceSuite))
}

func (s *ServiceSuite) SetupSuite() {
  s.db = openTestDB(s.T())
}

func (s *ServiceSuite) TearDownSuite() {
  s.db.Close()
}

func (s *ServiceSuite) SetupTest() {
  _, err := s.db.Exec("TRUNCATE orders RESTART IDENTITY")
  s.Require().NoError(err)
  s.svc = NewService(NewRepo(s.db), fixedClock{})
}
